namespace PCAnalyzer.Core;

/// <summary>Technical meaning shared by UI, reports and diagnostics. No hardware thresholds are inferred.</summary>
public sealed record MetricInfo(string Id, string Name, string Abbreviation, string Unit,
    string Description, string Importance, string Interpretation, string Influences, string Investigate, string Limitations)
{
    public string Heading => string.IsNullOrEmpty(Abbreviation) ? Name : $"{Name} · {Abbreviation}";
}

