    public static IReadOnlyList<MetricInfo> All => Definitions;
    public static MetricInfo Resolve(string key, string? unit = null)
    {
        var match = Definitions.FirstOrDefault(d => d.Id == key)
            ?? Definitions.Where(d => Matches(d.Id, key)).MaxBy(d => d.Id.Length);
        if (match is not null)
            return match with { Id = key, Name = key.StartsWith("cpu.logical.", StringComparison.Ordinal) && key.EndsWith(".percent", StringComparison.Ordinal)
                ? "Uso do processador lógico " + key[12..^8] : match.Name, Unit = unit ?? match.Unit };
        return Info(key, key.EndsWith(".telemetry", StringComparison.Ordinal) ? "Disponibilidade da fonte" : key, "", unit ?? "",
            "Leitura exposta pela fonte identificada no painel de origem. Consulte o método e a limitação reportados junto ao valor.",
            "Sem interpretação específica cadastrada; não há diagnóstico automático para esta leitura.", "Suporte do provedor, driver, permissões e intervalo.",
            "Confirme a semântica na documentação da fonte antes de tirar conclusões.", "Dados não disponíveis — verifique permissões ou suporte do dispositivo.");
    }
    private static bool Matches(string pattern, string key)
    {
        var wildcard = pattern.IndexOf('*');
        return wildcard >= 0 && key.Length > pattern.Length - 1 && key.StartsWith(pattern[..wildcard], StringComparison.Ordinal)
            && key.EndsWith(pattern[(wildcard + 1)..], StringComparison.Ordinal);
    }
